#!/bin/bash
# Install zeile: launcher in ~/.local/bin, desktop entry, and mime association.
# Run with --uninstall to remove everything this script wrote.
set -euo pipefail

SRC_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
readonly SRC_DIR
readonly BIN_DIR="$HOME/.local/bin"
readonly APP_DIR="$HOME/.local/share/applications"
readonly ICON_ROOT="$HOME/.local/share/icons/hicolor"
readonly ICON_NAME="zeile"
# hicolor dirs shipped by icons/hicolor/: the scalable SVG plus the fixed
# PNG sizes (regenerated by scripts/build_icons.py).
readonly -a ICON_DIRS=(scalable 16x16 24x24 32x32 48x48 64x64 128x128 256x256 512x512)
readonly LAUNCHER="$BIN_DIR/zeile"
readonly DESKTOP_FILE="$APP_DIR/zeile.desktop"

# File extension inside one hicolor dir: scalable holds the SVG, the fixed
# size dirs hold the PNG rendered at exactly that size.
icon_ext() {
    if [[ "$1" == "scalable" ]]; then
        printf 'svg'
    else
        printf 'png'
    fi
}

uninstall() {
    local dir
    rm -f "$LAUNCHER" "$DESKTOP_FILE"
    for dir in "${ICON_DIRS[@]}"; do
        rm -f "$ICON_ROOT/$dir/apps/$ICON_NAME.$(icon_ext "$dir")"
    done
    update-desktop-database "$APP_DIR" 2>/dev/null || true
    gtk-update-icon-cache -f -t "$ICON_ROOT" 2>/dev/null || true
    printf 'uninstalled: %s %s %s (icons under %s)\n' \
        "$LAUNCHER" "$DESKTOP_FILE" "$ICON_NAME" "$ICON_ROOT"
    printf 'note: text/markdown default handler is left as-is -- reassign it\n'
    printf 'yourself (xdg-mime default <app>.desktop text/markdown) if needed.\n'
    exit 0
}

if [[ "${1:-}" == "--uninstall" ]]; then
    uninstall
fi

# Fails loudly and specifically, not with a cryptic ImportError only when
# the user finally double-clicks a .md file. Each check names the exact
# package for the detected package manager, so the fix is a single
# copy-pasteable line, not a search. Arguments: description, then the
# pacman / apt / dnf package names, then the probe command.
install_hint() {
    local pacman_package="$1" apt_package="$2" dnf_package="$3"
    if command -v pacman >/dev/null 2>&1; then
        printf 'sudo pacman -S --needed %s' "$pacman_package"
    elif command -v apt-get >/dev/null 2>&1; then
        printf 'sudo apt install %s' "$apt_package"
    elif command -v dnf >/dev/null 2>&1; then
        printf 'sudo dnf install %s' "$dnf_package"
    else
        printf 'install the package providing: %s' "$pacman_package"
    fi
}

check_dependency() {
    local description="$1" pacman_package="$2" apt_package="$3" dnf_package="$4"
    shift 4
    if ! "$@" >/dev/null 2>&1; then
        printf 'missing dependency: %s\n' "$description" >&2
        printf '  fix: %s\n' "$(install_hint "$pacman_package" "$apt_package" "$dnf_package")" >&2
        exit 1
    fi
}

check_dependency "python3" "python" "python3" "python3" command -v python3
check_dependency "GTK4 GObject bindings (python-gobject)" \
    "python-gobject" "python3-gi gir1.2-gtk-4.0" "python3-gobject gtk4" \
    /usr/bin/python3 -c "import gi; gi.require_version('Gtk', '4.0'); from gi.repository import Gtk"
check_dependency "WebKitGTK 6.0 (webkitgtk-6.0)" \
    "webkitgtk-6.0" "gir1.2-webkit-6.0" "webkitgtk6.0" \
    /usr/bin/python3 -c "import gi; gi.require_version('WebKit', '6.0'); from gi.repository import WebKit"
check_dependency "python-markdown" "python-markdown" "python3-markdown" "python3-markdown" \
    /usr/bin/python3 -c "import markdown; markdown.markdown"
# Ubuntu 24.04 has no python3-nh3 package; Debian 13 does.
check_dependency "python-nh3" "python-nh3" \
    "python3-nh3 (Ubuntu 24.04: python3 -m pip install --user --break-system-packages nh3)" \
    "python3-nh3" \
    /usr/bin/python3 -c "import nh3; nh3.clean"
check_dependency "python-pymdown-extensions" \
    "python-pymdown-extensions" "python3-pymdownx" "python3-pymdown-extensions" \
    /usr/bin/python3 -c "import pymdownx.tasklist"
check_dependency "python-pygments" "python-pygments" "python3-pygments" "python3-pygments" \
    /usr/bin/python3 -c "import pygments; pygments.highlight"

mkdir -p "$BIN_DIR" "$APP_DIR"

# Compile translations (po/*.po -> locale/<lang>/LC_MESSAGES/zeile.mo), if
# msgfmt is available. The repo ships a pre-compiled de.po result for users
# without gettext installed; this just keeps it current after an edit.
if command -v msgfmt >/dev/null 2>&1; then
    for po_file in "$SRC_DIR"/po/*.po; do
        [[ -e "$po_file" ]] || continue
        lang="$(basename "$po_file" .po)"
        mo_dir="$SRC_DIR/locale/$lang/LC_MESSAGES"
        mkdir -p "$mo_dir"
        msgfmt "$po_file" -o "$mo_dir/zeile.mo"
    done
fi

# Launcher pins /usr/bin/python3: brew/mise pythons have no gi bindings.
# Checks its own target exists first -- a moved or deleted repo directory
# otherwise fails as a bare "No such file or directory" from python3 itself,
# which does not say which file it means.
cat > "$LAUNCHER" <<EOF
#!/bin/bash
SRC="$SRC_DIR/zeile.py"
if [[ ! -f "\$SRC" ]]; then
    printf 'zeile: %s no longer exists (did the repo move? re-run install.sh)\n' "\$SRC" >&2
    exit 1
fi
exec /usr/bin/python3 "\$SRC" "\$@"
EOF
chmod +x "$LAUNCHER"

# Freedesktop icon set. The Icon=zeile entry written below resolves against
# this hicolor tree: the scalable SVG and one PNG per fixed size.
for dir in "${ICON_DIRS[@]}"; do
    ext="$(icon_ext "$dir")"
    install -Dm 644 "$SRC_DIR/icons/hicolor/$dir/apps/$ICON_NAME.$ext" \
        "$ICON_ROOT/$dir/apps/$ICON_NAME.$ext"
done

update-icon-cache() {
    gtk-update-icon-cache -f -t "$ICON_ROOT" 2>/dev/null || true
}
update-icon-cache

cat > "$DESKTOP_FILE" <<EOF
[Desktop Entry]
Type=Application
Name=zeile
GenericName=Markdown Viewer
Comment=View markdown files
Exec=$LAUNCHER %f
Icon=zeile
Terminal=false
Categories=Utility;TextEditor;Viewer;
MimeType=text/markdown;text/x-markdown;
StartupWMClass=com.erdlabs.zeile
NoDisplay=false
EOF

update-desktop-database "$APP_DIR" 2>/dev/null || true
update-icon-cache
if command -v xdg-mime >/dev/null 2>&1; then
    xdg-mime default zeile.desktop text/markdown text/x-markdown
else
    printf 'xdg-mime not found: install xdg-utils, then run: xdg-mime default zeile.desktop text/markdown\n' >&2
fi

printf 'installed: %s\n' "$LAUNCHER"
if command -v xdg-mime >/dev/null 2>&1; then
    handler="$(xdg-mime query default text/markdown)"
    printf 'default handler: %s\n' "$handler"
fi
